class StokHabisError extends Error {
  constructor(menu) {
    super(`${menu} habis`);
    this.name = 'StokHabisError';
  }
}
const stok = { Kopi: 2, 'Es Krim': 0 };
async function pesan(menu) {
  await new Promise((r) => setTimeout(r, 5));
  if (!stok[menu]) throw new StokHabisError(menu);
  stok[menu] -= 1;
  return `${menu} dipesan`;
}
async function simpanPesanan(menu) {
  try {
    return await pesan(menu);
  } catch (e) {
    throw new Error('Gagal menyimpan pesanan', { cause: e });
  }
}
console.log(await simpanPesanan('Kopi'));
try {
  await simpanPesanan('Es Krim');
} catch (e) {
  console.log(e.message);
  console.log(e.cause.name, '-', e.cause.message);
  console.log(e.cause instanceof StokHabisError);
}

