const menu = { Kopi: 18000, Teh: 12000 };
async function pesan(nama) {
  if (!(nama in menu)) throw new Error(`${nama} tidak ada di menu`);
  return menu[nama];
}
try {
  await pesan('Jus');
} catch (e) {
  console.log('Ditolak:', e.message);
}

