class ValidasiError extends Error {
  constructor(pesan) {
    super(pesan);
    this.name = 'ValidasiError';
  }
}
async function cekUmur(umur) {
  if (umur < 0) throw new ValidasiError('Umur tidak valid');
  return umur;
}
try {
  await cekUmur(-1);
} catch (e) {
  console.log(e instanceof ValidasiError, e.message);
}
